#!/usr/bin/env python3
"""Bounded seed-first check, independent cell-array generators; no schedules."""
import datetime
import hashlib
import json
import os
import pathlib
import platform
import resource
import signal
import subprocess
import sys
import tempfile
import time

ROOT = pathlib.Path(os.environ.get('RULE30_REPLAY_ROOT', '/home/ryan/rule30-lab'))
OUT = pathlib.Path(os.environ.get('RULE30_REPLAY_OUTPUT', '/tmp/astra_cyclic_seed_independent.json'))
START = time.monotonic()
resource.setrlimit(resource.RLIMIT_AS, (1 << 30, 1 << 30))
resource.setrlimit(resource.RLIMIT_CPU, (120, 120))
signal.alarm(120)
affinity = sorted(os.sched_getaffinity(0))
os.sched_setaffinity(0, {affinity[0]})

def sha(b):
    return hashlib.sha256(b).hexdigest()

def canonical(obj):
    return json.dumps(obj, sort_keys=True, separators=(',', ':')).encode()

def cells(n):
    return [int(d) for d in bin(n)[2:][::-1]]

def value(a):
    return sum(b * 2**i for i, b in enumerate(a))

def T(n):
    a = cells(n)
    def bit(i):
        return a[i] if 0 <= i < len(a) else 0
    return value([(bit(i) + int(bool(bit(i-1) or bit(i-2)))) % 2
                  for i in range(len(a)+2)])

def generators(n):
    t = cells(T(n))
    t[0] = 1 - t[0]
    # P via the independently evaluated odd-section identity.
    return T(n), value(t), T(2*n+1)//2

def A(n):
    return value(cells(T(n))[2:])

def aged(s, L):
    for _ in range(L):
        s = {A(v) for v in s}
    return s

input_path = ROOT / 'results/problem1/20260905_frontier_head_primary.json'
input_bytes = input_path.read_bytes()
stored = json.loads(input_bytes)['result_summary']['head_data']['frontiers']
F = {}
failures = []
for a, root in [('p', 3), ('u', 1)]:
    F[a] = {1: {root}}
    for k in range(2, 10):
        F[a][k] = {w for v in F[a][k-1] for w in generators(v)}
    for k in range(1, 10):
        if sorted(F[a][k]) != stored[a][str(k)]:
            failures.append(['frontier', a, k])

def mask(a, h, q):
    assert h >= 1
    return sum(2**d for d in range(4) if 4*q+d in F[a][h+1])

rows = []
for k in range(2, 10):
    for a in ['p', 'u']:
        for x in sorted(F[a][k]):
            for L in sorted({k-3, k-2, k-1}):
                if not 1 <= L < k:
                    continue
                s = k-1-L
                modulus = 4**L
                residue = x % modulus
                seeds = sorted(aged(F[a][s], L)) if s >= 1 else None
                if seeds is not None:
                    raw = [q*modulus+residue for q in seeds
                           if q*modulus+residue in F[a][k-1]]
                else:
                    # Boundary is explicitly checked, not assumed from a lemma.
                    raw = sorted(y for y in F[a][k-1] if y % modulus == residue)
                    if raw:
                        failures.append(['raw-separation', a, k, x, L])
                belief, details = [], []
                for y in raw:
                    steps = []
                    for j in range(L):
                        ch, sh = k-1-j, k-2-j
                        if sh < 1:
                            raise AssertionError('Unexpected boundary candidate')
                        cq, sq = x//4**(j+1), y//4**(j+1)
                        m, n = mask(a, ch, cq), mask(a, sh, sq)
                        subset = all(not (m // 2**d % 2) or (n // 2**d % 2)
                                     for d in range(4))
                        steps.append([j, ch, sh, cq, sq, m, n, bool(subset)])
                    details.append({'y': y, 'steps': steps})
                    if all(step[-1] for step in steps):
                        cost = sum(step[-2] != 15 for step in steps)
                        belief.append({'y': y, 'cost': cost})
                if seeds is not None and len(belief) > len(seeds):
                    failures.append(['seed-bound', a, k, x, L])
                applies = ((k >= 3 and L >= k-2) or
                           (a == 'p' and k >= 5 and L >= k-3) or
                           (a == 'u' and k >= 6 and L >= k-3))
                if applies and belief:
                    failures.append(['empty-threshold', a, k, x, L])
                rows.append({'phase': a, 'k': k, 'x': x, 'L': L,
                             'seed_heads': seeds, 'raw_shadow_endpoints': raw,
                             'belief': belief, 'raw_mask_checks': details,
                             'signed_mass': sum((-1)**b['cost'] for b in belief)})

small = {}
for a in ['p', 'u']:
    small[a] = {}
    for h in range(1, 5):
        s = set(F[a][h])
        layers = [sorted(s)]
        for _ in range(5):
            s = {A(v) for v in s}
            layers.append(sorted(s))
        small[a][str(h)] = {
            'frontier': sorted(F[a][h]), 'A_images_0_through_5': layers,
            'masks': [[q, mask(a, h, q)] for q in sorted(F[a][h])],
            'children': [[v, list(generators(v))] for v in sorted(F[a][h])]}

exceptions = [{'phase': r['phase'], 'k': r['k'], 'x': r['x'], 'L': r['L'],
               'belief': r['belief'], 'signed_mass': r['signed_mass']}
              for r in rows if r['belief']]
summary = {'completed': True, 'validation_failures': failures,
           'frontier_counts': {a: [len(F[a][k]) for k in range(1, 10)] for a in F},
           'checked_frontier_sets': 18, 'cylinders_checked': len(rows),
           'nonempty_cylinders': len(exceptions), 'nonempty_rows': exceptions,
           'rows': rows, 'small_certificates': small}
source = pathlib.Path(__file__).read_bytes()
cpu = next((line.split(':', 1)[1].strip() for line in
            pathlib.Path('/proc/cpuinfo').read_text().splitlines()
            if line.startswith('model name')), 'unknown')
record = {
    'experiment_id': 'problem1-cyclic-seed-boundary-independent-20260905',
    'timestamp_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
    'git_commit': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
    'question': 'problem1',
    'hypothesis': 'Both phases empty at L=k-2 (k>=3); p empty at L=k-3 (k>=5); u empty at L=k-3 (k>=6).',
    'backend': 'python-cell-array-odd-section-seed-first',
    'parameters': {'k_min': 2, 'k_max': 9, 'phases': ['p', 'u'],
                   'L': 'distinct k-3,k-2,k-1 with 1<=L<k',
                   'cpu_seconds_limit': 120, 'address_space_bytes': 1 << 30,
                   'wall_alarm_seconds': 120, 'input_path': str(input_path.relative_to(ROOT)),
                   'mask_certificates_h': [1, 2, 3, 4], 'frontier_base_levels': [1, 2, 3, 4, 5]},
    'hardware': {'cpu_model': cpu, 'logical_cpus': os.cpu_count(),
                 'original_affinity': affinity, 'executed_affinity': [affinity[0]],
                 'physical_memory_bytes': os.sysconf('SC_PAGE_SIZE')*os.sysconf('SC_PHYS_PAGES')},
    'software': {'python': sys.version, 'platform': platform.platform(), 'executable': sys.executable},
    'runtime_seconds': time.monotonic()-START,
    'result_hashes': {'input_sha256': sha(input_bytes), 'source_sha256': sha(source),
                      'result_summary_sha256': sha(canonical(summary))},
    'source_text': source.decode(), 'result_summary': summary,
    'status': 'finite-exhaustive',
    'interpretation': 'Finite falsification of the specified empty layers; infinite proofs must use exact head marginals and base masks.',
    'proof_scope': 'All ordinary cylinders in the stated finite domain; no return-occurrence assertion.',
    'limitations': ['No frontiers above level9 or branch schedules were tested.',
                    'Dominant emptiness is different from raw-shadow separation.',
                    'Aged head membership is necessary, not sufficient.',
                    'This record does not prove any occurrence bound or Problem1.']}
OUT.parent.mkdir(parents=True, exist_ok=True)
with tempfile.NamedTemporaryFile('w', dir=OUT.parent, delete=False) as f:
    json.dump(record, f, indent=2, sort_keys=True)
    f.write('\n'); f.flush(); os.fsync(f.fileno()); temp = f.name
os.replace(temp, OUT)
print(json.dumps({'output': str(OUT), 'cylinders': len(rows),
                  'nonempty': len(exceptions), 'failures': failures, 'exceptions': exceptions}))
